[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ClipCast — One video is worth a thousand words</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --blue: #1868DB;
  --orange: #FF613D;
  --dark: #292A2E;
  --gray: #6B7280;
  --light-gray: #F3F4F6;
  --border: #E5E7EB;
  --white: #FFFFFF;
  --radius: 12px;
  --radius-lg: 20px;
}
body { font-family: 'Inter', sans-serif; color: var(--dark); background: var(--white); line-height: 1.6; }
a { text-decoration: none; color: inherit; }
img { max-width: 100%; }

/* NAV */
nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
}
.nav-inner {
  max-width: 1200px; margin: 0 auto;
  display: flex; align-items: center; gap: 32px;
  height: 64px;
}
.nav-logo { font-size: 22px; font-weight: 800; color: var(--blue); letter-spacing: -0.5px; }
.nav-logo span { color: var(--orange); }
.nav-links { display: flex; align-items: center; gap: 28px; margin-left: auto; }
.nav-links a { font-size: 14px; font-weight: 500; color: var(--gray); transition: color .2s; }
.nav-links a:hover { color: var(--dark); }
.nav-cta {
  background: var(--blue); color: var(--white) !important;
  padding: 9px 20px; border-radius: 8px; font-weight: 600 !important;
  transition: background .2s, transform .15s !important;
}
.nav-cta:hover { background: #1558c0 !important; transform: translateY(-1px); }

/* BUTTONS */
.btn-primary {
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--blue); color: var(--white);
  padding: 14px 28px; border-radius: 10px;
  font-size: 16px; font-weight: 600;
  transition: background .2s, transform .15s, box-shadow .2s;
  cursor: pointer; border: none;
}
.btn-primary:hover { background: #1558c0; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(24,104,219,.3); }
.btn-secondary {
  display: inline-flex; align-items: center; gap: 8px;
  background: transparent; color: var(--dark);
  padding: 14px 28px; border-radius: 10px;
  font-size: 16px; font-weight: 600; border: 2px solid var(--border);
  transition: border-color .2s, transform .15s;
  cursor: pointer;
}
.btn-secondary:hover { border-color: var(--dark); transform: translateY(-2px); }
.btn-sm { padding: 10px 20px; font-size: 14px; }

/* HERO */
.hero {
  background: linear-gradient(135deg, #EFF4FF 0%, #F8F5FF 50%, #FFF5F3 100%);
  padding: 80px 24px 100px;
  text-align: center;
}
.hero-inner { max-width: 860px; margin: 0 auto; }
.hero h1 {
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 900; line-height: 1.1;
  letter-spacing: -2px; color: var(--dark);
  margin-bottom: 24px;
}
.hero h1 em { font-style: normal; color: var(--blue); }
.hero p { font-size: 20px; color: var(--gray); margin-bottom: 40px; max-width: 600px; margin-left: auto; margin-right: auto; }
.hero-ctas { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; margin-bottom: 60px; }
.hero-video {
  background: var(--dark);
  border-radius: var(--radius-lg);
  aspect-ratio: 16/9;
  max-width: 900px; margin: 0 auto;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 40px 80px rgba(0,0,0,.2);
  overflow: hidden; position: relative;
}
.hero-video-inner {
  width: 100%; height: 100%; display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
}
.play-btn {
  width: 72px; height: 72px; background: var(--white);
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
  box-shadow: 0 8px 32px rgba(0,0,0,.3);
  cursor: pointer; transition: transform .2s;
}
.play-btn:hover { transform: scale(1.1); }
.play-btn svg { width: 28px; height: 28px; fill: var(--blue); margin-left: 4px; }

/* LOGO BAR */
.logo-bar { padding: 40px 24px; border-bottom: 1px solid var(--border); }
.logo-bar-inner { max-width: 1200px; margin: 0 auto; text-align: center; }
.logo-bar p { font-size: 14px; color: var(--gray); margin-bottom: 24px; font-weight: 500; }
.logo-row { display: flex; align-items: center; justify-content: center; gap: 40px; flex-wrap: wrap; }
.logo-item {
  font-size: 18px; font-weight: 700; color: #9CA3AF;
  letter-spacing: -0.5px; transition: color .2s;
}
.logo-item:hover { color: var(--gray); }

/* SECTIONS */
.section { padding: 80px 24px; }
.section-alt { background: var(--light-gray); }
.section-inner { max-width: 1200px; margin: 0 auto; }
.section-tag {
  display: inline-flex; align-items: center; gap: 6px;
  background: #EFF4FF; color: var(--blue);
  padding: 6px 14px; border-radius: 20px;
  font-size: 13px; font-weight: 600;
  margin-bottom: 16px;
}
.section-tag .new { background: var(--orange); color: white; border-radius: 4px; padding: 1px 6px; font-size: 11px; }
h2.section-title {
  font-size: clamp(28px, 4vw, 48px); font-weight: 800;
  line-height: 1.15; letter-spacing: -1px;
  margin-bottom: 16px;
}
.section-subtitle { font-size: 18px; color: var(--gray); max-width: 560px; margin-bottom: 40px; }

/* FEATURE HIGHLIGHT */
.feature-highlight .section-inner {
  display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center;
}
.feature-visual {
  background: linear-gradient(135deg, #1868DB 0%, #6B21A8 100%);
  border-radius: var(--radius-lg); aspect-ratio: 4/3;
  display: flex; align-items: center; justify-content: center;
  padding: 32px; position: relative; overflow: hidden;
}
.feature-visual::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 70% 30%, rgba(255,255,255,.15) 0%, transparent 60%);
}
.feature-mock {
  background: rgba(255,255,255,.1); backdrop-filter: blur(8px);
  border-radius: 12px; padding: 16px; width: 100%;
  border: 1px solid rgba(255,255,255,.2);
}
.mock-header { display: flex; gap: 8px; margin-bottom: 12px; }
.mock-dot { width: 10px; height: 10px; border-radius: 50%; }
.mock-dot.red { background: #FF5F57; }
.mock-dot.yellow { background: #FFBD2E; }
.mock-dot.green { background: #28C940; }
.mock-lines { display: flex; flex-direction: column; gap: 8px; }
.mock-line { height: 8px; background: rgba(255,255,255,.3); border-radius: 4px; }
.mock-line.short { width: 60%; }
.mock-line.shorter { width: 40%; }

/* VIDEO EDITOR */
.editor-features { display: flex; flex-direction: column; gap: 24px; margin-bottom: 40px; }
.editor-feature { display: flex; gap: 16px; }
.editor-icon {
  width: 48px; height: 48px; flex-shrink: 0;
  background: #EFF4FF; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 22px;
}
.editor-feature h3 { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.editor-feature p { font-size: 14px; color: var(--gray); }

/* USE CASES */
.use-cases-grid { display: grid; grid-template-columns: repeat(4,1fr); gap: 20px; margin-bottom: 40px; }
.use-case-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 28px; border: 1px solid var(--border);
  transition: box-shadow .2s, transform .2s;
}
.use-case-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,.1); transform: translateY(-4px); }
.uc-icon { font-size: 32px; margin-bottom: 16px; }
.use-case-card h3 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
.use-case-card p { font-size: 14px; color: var(--gray); }

/* FEATURES GRID */
.features-grid-list {
  display: grid; grid-template-columns: repeat(4,1fr); gap: 16px; margin-bottom: 40px;
}
.feature-item {
  background: var(--white); border-radius: var(--radius);
  padding: 24px; border: 1px solid var(--border);
  display: flex; gap: 12px; align-items: flex-start;
  transition: box-shadow .2s;
}
.feature-item:hover { box-shadow: 0 4px 16px rgba(0,0,0,.08); }
.feature-check {
  width: 24px; height: 24px; background: #EFF4FF; border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 12px; color: var(--blue); font-weight: 700;
}
.feature-item span { font-size: 14px; font-weight: 500; padding-top: 2px; }

/* INTEGRATIONS */
.integrations-grid {
  display: grid; grid-template-columns: repeat(6,1fr); gap: 16px; margin-bottom: 40px;
}
.integration-badge {
  background: var(--white); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px;
  display: flex; align-items: center; justify-content: center;
  font-size: 13px; font-weight: 600; color: var(--gray);
  transition: box-shadow .2s; text-align: center;
}
.integration-badge:hover { box-shadow: 0 4px 16px rgba(0,0,0,.1); color: var(--dark); }

/* SECURITY */
.security-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 20px; }
.security-item {
  background: var(--white); border-radius: var(--radius);
  padding: 24px; border: 1px solid var(--border);
  display: flex; gap: 14px; align-items: flex-start;
}
.security-icon {
  width: 44px; height: 44px; background: linear-gradient(135deg,#1868DB,#6B21A8);
  border-radius: 10px; display: flex; align-items: center; justify-content: center;
  font-size: 20px; flex-shrink: 0;
}
.security-item h3 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.security-item p { font-size: 13px; color: var(--gray); }

/* BLOG */
.blog-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 24px; }
.blog-card {
  background: var(--white); border-radius: var(--radius-lg);
  overflow: hidden; border: 1px solid var(--border);
  transition: box-shadow .2s, transform .2s;
}
.blog-card:hover { box-shadow: 0 12px 40px rgba(0,0,0,.1); transform: translateY(-4px); }
.blog-thumb {
  height: 180px; display: flex; align-items: center; justify-content: center;
  font-size: 48px;
}
.blog-thumb-1 { background: linear-gradient(135deg,#EFF4FF,#E0ECFF); }
.blog-thumb-2 { background: linear-gradient(135deg,#FFF5F3,#FFE8E1); }
.blog-content { padding: 24px; }
.blog-tag { font-size: 12px; font-weight: 600; color: var(--blue); margin-bottom: 8px; }
.blog-content h3 { font-size: 18px; font-weight: 700; margin-bottom: 8px; line-height: 1.4; }
.blog-content p { font-size: 14px; color: var(--gray); }

/* TESTIMONIALS */
.testimonials-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }
.testimonial-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 28px; border: 1px solid var(--border);
  transition: box-shadow .2s;
}
.testimonial-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,.08); }
.testimonial-stars { color: #F59E0B; font-size: 16px; margin-bottom: 12px; }
.testimonial-text { font-size: 15px; color: var(--dark); margin-bottom: 20px; line-height: 1.7; font-style: italic; }
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.author-avatar {
  width: 40px; height: 40px; border-radius: 50%;
  background: linear-gradient(135deg, var(--blue), #6B21A8);
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 700; color: white; flex-shrink: 0;
}
.author-name { font-size: 14px; font-weight: 700; }
.author-role { font-size: 12px; color: var(--gray); }

/* ENTERPRISE CTA */
.enterprise-cta-block {
  background: linear-gradient(135deg,#1868DB 0%,#6B21A8 100%);
  padding: 60px 24px; text-align: center; color: white;
}
.enterprise-cta-block h2 { font-size: 36px; font-weight: 800; margin-bottom: 12px; letter-spacing: -1px; }
.enterprise-cta-block p { font-size: 18px; opacity: .85; margin-bottom: 32px; }
.btn-white {
  background: white; color: var(--blue);
  padding: 14px 28px; border-radius: 10px;
  font-size: 16px; font-weight: 700;
  display: inline-flex; align-items: center; gap: 8px;
  transition: transform .15s, box-shadow .2s;
}
.btn-white:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,.2); }

/* CTA BANNER */
.cta-banner {
  background: var(--dark); padding: 80px 24px; text-align: center; color: white;
}
.cta-banner h2 { font-size: 48px; font-weight: 900; margin-bottom: 16px; letter-spacing: -1.5px; }
.cta-banner p { font-size: 16px; opacity: .6; margin-top: 16px; }

/* FOOTER */
footer {
  background: #F9FAFB; border-top: 1px solid var(--border);
  padding: 60px 24px 32px;
}
.footer-inner { max-width: 1200px; margin: 0 auto; }
.footer-grid {
  display: grid; grid-template-columns: 2fr repeat(5,1fr); gap: 40px; margin-bottom: 48px;
}
.footer-brand p { font-size: 14px; color: var(--gray); margin-top: 12px; max-width: 200px; }
.footer-col h4 { font-size: 13px; font-weight: 700; color: var(--dark); margin-bottom: 16px; letter-spacing: 0.5px; text-transform: uppercase; }
.footer-col a { display: block; font-size: 13px; color: var(--gray); margin-bottom: 8px; transition: color .2s; }
.footer-col a:hover { color: var(--dark); }
.footer-bottom {
  border-top: 1px solid var(--border); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px;
}
.footer-bottom p { font-size: 13px; color: var(--gray); }
.footer-legal { display: flex; gap: 20px; }
.footer-legal a { font-size: 13px; color: var(--gray); transition: color .2s; }
.footer-legal a:hover { color: var(--dark); }

/* COOKIE BANNER */
.cookie-banner {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  z-index: 1000; width: calc(100% - 48px); max-width: 900px;
  background: var(--dark); color: white;
  border-radius: var(--radius-lg); padding: 24px 28px;
  box-shadow: 0 20px 60px rgba(0,0,0,.3);
  display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
}
.cookie-text { flex: 1; min-width: 200px; }
.cookie-text p { font-size: 14px; opacity: .85; line-height: 1.6; }
.cookie-text a { color: #93C5FD; text-decoration: underline; }
.cookie-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.cookie-btn {
  padding: 10px 20px; border-radius: 8px; font-size: 14px; font-weight: 600;
  cursor: pointer; border: none; transition: transform .15s, opacity .2s;
}
.cookie-btn:hover { transform: translateY(-1px); opacity: .9; }
.cookie-accept { background: var(--blue); color: white; }
.cookie-reject { background: rgba(255,255,255,.15); color: white; }
.cookie-manage { background: transparent; color: rgba(255,255,255,.7); border: 1px solid rgba(255,255,255,.3) !important; }

/* COOKIE MODAL */
.cookie-modal-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,.5);
  z-index: 2000; display: flex; align-items: center; justify-content: center;
  padding: 24px; opacity: 0; pointer-events: none; transition: opacity .3s;
}
.cookie-modal-overlay.active { opacity: 1; pointer-events: all; }
.cookie-modal {
  background: white; border-radius: var(--radius-lg);
  padding: 32px; max-width: 520px; width: 100%;
  box-shadow: 0 20px 60px rgba(0,0,0,.2);
}
.cookie-modal h3 { font-size: 22px; font-weight: 800; margin-bottom: 8px; }
.cookie-modal > p { font-size: 14px; color: var(--gray); margin-bottom: 24px; }
.cookie-category {
  border: 1px solid var(--border); border-radius: var(--radius);
  padding: 16px; margin-bottom: 12px;
}
.cookie-cat-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }
.cookie-cat-header h4 { font-size: 15px; font-weight: 600; }
.toggle-switch {
  width: 44px; height: 24px; background: #E5E7EB; border-radius: 12px;
  cursor: pointer; position: relative; transition: background .2s;
  border: none; flex-shrink: 0;
}
.toggle-switch.on { background: var(--blue); }
.toggle-switch::after {
  content: ''; position: absolute; top: 2px; left: 2px;
  width: 20px; height: 20px; background: white; border-radius: 50%;
  transition: left .2s; box-shadow: 0 1px 4px rgba(0,0,0,.2);
}
.toggle-switch.on::after { left: 22px; }
.cookie-category p { font-size: 13px; color: var(--gray); }
.cookie-modal-actions { display: flex; gap: 12px; margin-top: 24px; }
.cookie-modal-actions button {
  flex: 1; padding: 12px; border-radius: 8px; font-size: 14px; font-weight: 600;
  cursor: pointer; border: none; transition: transform .15s;
}
.cookie-modal-actions button:hover { transform: translateY(-1px); }
.modal-save { background: var(--blue); color: white; }
.modal-accept { background: var(--light-gray); color: var(--dark); }

/* STATS STRIP */
.stats-strip { background: var(--blue); padding: 48px 24px; color: white; }
.stats-inner { max-width: 900px; margin: 0 auto; display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; text-align: center; }
.stat-num { font-size: 56px; font-weight: 900; letter-spacing: -2px; line-height: 1; }
.stat-label { font-size: 14px; opacity: .8; margin-top: 8px; }

@media (max-width: 768px) {
  .feature-highlight .section-inner { grid-template-columns: 1fr; gap: 40px; }
  .use-cases-grid { grid-template-columns: repeat(2,1fr); }
  .features-grid-list { grid-template-columns: repeat(2,1fr); }
  .testimonials-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .integrations-grid { grid-template-columns: repeat(3,1fr); }
  .blog-grid { grid-template-columns: 1fr; }
  .security-grid { grid-template-columns: 1fr; }
  .stats-inner { grid-template-columns: 1fr; }
  .nav-links .hide-mobile { display: none; }
}
</style>
</head>
<body>

<!-- NAV -->
<nav>
  <div class="nav-inner">
    <a href="index.html" class="nav-logo">Clip<span>Cast</span></a>
    <div class="nav-links">
      <a href="enterprise.html" class="hide-mobile">Enterprise</a>
      <a href="pricing.html" class="hide-mobile">Pricing</a>
      <a href="login.html">Sign In</a>
      <a href="signup.html" class="nav-cta">Get Started for free</a>
    </div>
  </div>
</nav>

<!-- HERO -->
<section class="hero">
  <div class="hero-inner">
    <h1>One video is worth<br><em>a thousand words</em></h1>
    <p>Easily record and share AI-powered video messages with your teammates and customers to supercharge productivity</p>
    <div class="hero-ctas">
      <a href="signup.html" class="btn-primary">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" width="18" height="18"><path d="M15 10l-6 6M15 10H9m6 0v6"/></svg>
        Get ClipCast for free
