        Install Chrome Extension
      </a>
    </div>
    <div class="hero-video">
      <div class="hero-video-inner">
        <div class="play-btn">
          <svg viewBox="0 0 24 24"><path d="M5 3l14 9-14 9V3z"/></svg>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- LOGO BAR -->
<section class="logo-bar">
  <div class="logo-bar-inner">
    <p>Millions of people across 400,000 companies choose ClipCast</p>
    <div class="logo-row">
      <span class="logo-item">Stripe</span>
      <span class="logo-item">Dropbox</span>
      <span class="logo-item">HubSpot</span>
      <span class="logo-item">Atlassian</span>
      <span class="logo-item">Launchdarkly</span>
      <span class="logo-item">Netflix</span>
    </div>
  </div>
</section>

<!-- FEATURE HIGHLIGHT: AI Bug Reports -->
<section class="section feature-highlight">
  <div class="section-inner">
    <div>
      <div class="section-tag"><span class="new">New!</span> AI Bug Reports</div>
      <h2 class="section-title">Ship faster with AI bug reports</h2>
      <p class="section-subtitle">Record a quick walkthrough and let ClipCast's AI turn it into a fully populated Jira work item in a few clicks. ClipCast automatically captures the technical details devs need — device/browser/OS, console errors, and network activity — to pinpoint the problem fast and move work forward.</p>
      <a href="#" class="btn-primary btn-sm">Learn more →</a>
    </div>
    <div class="feature-visual">
      <div class="feature-mock">
        <div class="mock-header">
          <div class="mock-dot red"></div>
          <div class="mock-dot yellow"></div>
          <div class="mock-dot green"></div>
        </div>
        <div class="mock-lines">
          <div class="mock-line"></div>
          <div class="mock-line short"></div>
          <div class="mock-line"></div>
          <div class="mock-line shorter"></div>
          <div class="mock-line short"></div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- SCREEN RECORDER -->
<section class="section section-alt">
  <div class="section-inner" style="text-align:center">
    <h2 class="section-title" style="max-width:640px;margin:0 auto 16px">The easiest screen recorder you'll ever use</h2>
    <p class="section-subtitle" style="margin:0 auto 40px">Record in a few clicks. Share anywhere. Collaborate better.</p>
