<script>
let billingMode = 'monthly';

function setBilling(mode) {
  billingMode = mode;
  document.getElementById('monthlyBtn').classList.toggle('active', mode === 'monthly');
  document.getElementById('annualBtn').classList.toggle('active', mode === 'annual');

  document.querySelectorAll('.plan-price[data-monthly]').forEach(el => {
    const monthly = parseInt(el.dataset.monthly);
    const annual = parseInt(el.dataset.annual);
    const price = mode === 'annual' ? annual : monthly;
    el.querySelector('.price-num').textContent = price;
  });

  document.querySelectorAll('.annual-note').forEach(el => {
    el.style.display = mode === 'annual' ? 'block' : 'none';
  });
}

function updateSlider(input) {
  const val = parseInt(input.value);
  const max = parseInt(input.max);
  const pct = ((val - 1) / (max - 1) * 100).toFixed(0);
  input.style.setProperty('--fill', pct + '%');
  const label = val === 1 ? '1 user' : val >= max ? `${max}+ users` : `${val} users`;
  document.getElementById('sliderValue').textContent = label;
}

function toggleFaq(btn) {
  const item = btn.closest('.faq-item');
  const wasOpen = item.classList.contains('open');
  document.querySelectorAll('.faq-item.open').forEach(i => i.classList.remove('open'));
  if (!wasOpen) item.classList.add('open');
}

function toggleFeatures(btn) {
  const card = btn.closest('.plan-card');
  const extra = card.querySelector('.plan-extra-features');
  const isOpen = extra.classList.contains('open');
  extra.classList.toggle('open', !isOpen);
  btn.classList.toggle('open', !isOpen);
  btn.querySelector('.chevron').textContent = isOpen ? '▼' : '▲';
  btn.childNodes[0].textContent = isOpen ? 'See all features ' : 'Hide features ';
}
</script>
